Repair the complete source below. `clampGridLevel(level, limits)` must accept a finite numeric `level` and a plain object containing finite numeric `min` and `max`, with `min <= max`. Return `min` below the range, `max` above the range, and the original level at both boundaries and everywhere inside the range. Throw `TypeError` for malformed values and `RangeError` for reversed limits. Do not mutate `limits`. Export exactly the function with `module.exports = clampGridLevel`. Return a corrected complete source file.

```javascript
'use strict';

function clampGridLevel(level, limits) {
  if (!Number.isFinite(level) || !limits || typeof limits !== 'object' ||
      Array.isArray(limits) || !Number.isFinite(limits.min) ||
      !Number.isFinite(limits.max)) {
    throw new TypeError('invalid level or limits');
  }
  if (limits.min > limits.max) {
    throw new RangeError('min must not exceed max');
  }
  if (level < limits.min) return limits.min;
  if (level >= limits.max) return limits.max - 1;
  return level;
}

module.exports = clampGridLevel;
```

