'use strict';

const assert = require('node:assert');
const clampGridLevel = require('./solution');

assert.strictEqual(typeof clampGridLevel, 'function');

const limits = Object.freeze({ min: 2, max: 8 });
assert.strictEqual(clampGridLevel(-10, limits), 2);
assert.strictEqual(clampGridLevel(2, limits), 2);
assert.strictEqual(clampGridLevel(5.5, limits), 5.5);
assert.strictEqual(clampGridLevel(8, limits), 8);
assert.strictEqual(clampGridLevel(100, limits), 8);
assert.deepStrictEqual(limits, { min: 2, max: 8 });

assert.strictEqual(clampGridLevel(3, { min: 3, max: 3 }), 3);
assert.strictEqual(clampGridLevel(-0, { min: -1, max: 1 }), -0);
assert.strictEqual(clampGridLevel(-4, { min: -4.5, max: -2.5 }), -4);

for (const level of [NaN, Infinity, -Infinity, '3', null]) {
  assert.throws(() => clampGridLevel(level, { min: 0, max: 5 }), TypeError);
}
for (const badLimits of [
  null,
  [],
  'limits',
  {},
  { min: '0', max: 1 },
  { min: 0, max: NaN },
  { min: -Infinity, max: 1 }
]) {
  assert.throws(() => clampGridLevel(0, badLimits), TypeError);
}
assert.throws(() => clampGridLevel(5, { min: 10, max: 2 }), RangeError);

